constexpr const char* Names[54] = {"ceil_f32 v4", "ceil_f32 v5", "floor_f32 v4", "floor_f32 v5", "trunc_f32 v4", "trunc_f32 v5", "rndne_f32 v4", "rndne_f32 v5", "fract_f32 v4", "fract_f32 v5", "frexp_exp_i32_f32 v4", "frexp_exp_i32_f32 v5", "frexp_mant_f32 v4", "frexp_mant_f32 v5", "sqrt_f32 v4", "sqrt_f32 v5", "rsq_f32 v4", "rsq_f32 v5", "rcp_f32 v4", "rcp_f32 v5", "rcp_iflag_f32 v4", "rcp_iflag_f32 v5", "log_f32 v4", "log_f32 v5", "exp_f32 v4", "exp_f32 v5", "sin_f32 v4", "sin_f32 v5", "cos_f32 v4", "cos_f32 v5", "ceil_f16 v6", "ceil_f16 v8", "floor_f16 v6", "floor_f16 v8", "trunc_f16 v6", "trunc_f16 v8", "rndne_f16 v6", "rndne_f16 v8", "fract_f16 v6", "fract_f16 v8", "sqrt_f16 v6", "sqrt_f16 v8", "rsq_f16 v6", "rsq_f16 v8", "rcp_f16 v6", "rcp_f16 v8", "log_f16 v6", "log_f16 v8", "exp_f16 v6", "exp_f16 v8", "sin_f16 v6", "sin_f16 v8", "cos_f16 v6", "cos_f16 v8"};
